export const locales = ['zh-CN', 'zh-TW', 'en', 'ja', 'ru', 'fr', 'vi'] as const
export type AppLocale = (typeof locales)[number]

export const defaultLocale: AppLocale = 'en'

export const localeLabels: Record<AppLocale, string> = {
  'zh-CN': '简体中文',
  'zh-TW': '繁體中文',
  en: 'English',
  ja: '日本語',
  ru: 'Русский',
  fr: 'Français',
  vi: 'Tiếng Việt',
}

export function isAppLocale(value: string | undefined): value is AppLocale {
  return locales.includes(value as AppLocale)
}

export function resolvePreferredLocale(): AppLocale {
  if (typeof window === 'undefined') return defaultLocale
  const saved = window.localStorage.getItem('partokens-locale')
  if (isAppLocale(saved ?? undefined)) return saved as AppLocale
  const browser = window.navigator.language
  if (browser.toLowerCase().startsWith('zh-tw') || browser.toLowerCase().startsWith('zh-hk')) return 'zh-TW'
  if (browser.toLowerCase().startsWith('zh')) return 'zh-CN'
  const short = browser.split('-')[0]
  if (isAppLocale(short)) return short
  return defaultLocale
}

